css:
VllmSetupView > #vllm-local-setup,
VllmSetupView > #vllm-existing-setup,
VllmSetupView > #vllm-current-server,
VllmSetupView > #vllm-next-restart {
    height: auto;
}
VllmSetupView > #vllm-next-action,
VllmSetupView > .vllm-mode-actions,
VllmSetupView > .vllm-profile-actions,
VllmSetupView > .vllm-source-actions,
VllmSetupView > .vllm-console-actions {
    height: 3;
}

LibraryCharacterRepairDialog { align: center middle; }
LibraryCharacterRepairDialog > Container {
    width: 76; max-width: 96%; height: auto; max-height: 90%;
    border: thick $accent; background: $surface; padding: 1 2;
}
LibraryCharacterRepairDialog Select { width: 100%; }
LibraryCharacterRepairDialog Horizontal { height: auto; }
LibraryCharacterRepairDialog Button { min-width: 14; margin-right: 1; }

SkillImportChoiceModal {
    align: center middle;
    background: $background 75%;
}
#skill-import-choice {
    width: 88;
    max-width: 100%;
    height: 28;
    max-height: 100%;
    min-height: 14;
    background: $panel;
    border: round $accent;
    padding: 1 2;
}
#skill-import-choice-title,
#skill-import-choice-help {
    height: auto;
}
#skill-import-choice-list {
    height: 1fr;
    min-height: 4;
    background: $surface-darken-1;
}
#skill-import-choice-actions {
    height: 3;
}
#skill-import-choice-actions Button {
    width: auto;
    min-width: 10;
    height: 3;
    margin-right: 1;
}

RoleplayDraftNavigationDialog { align: center middle; }
RoleplayDraftNavigationDialog > Container {
    width: 72; max-width: 96%; height: auto; border: thick $accent;
    background: $surface; padding: 1 2;
}
RoleplayDraftNavigationDialog Vertical { height: auto; }
RoleplayDraftNavigationDialog Button { width: 100%; margin-top: 1; }

RoleplayDraftNavigationDialog { align: center middle; }
RoleplayDraftNavigationDialog > Container {
    width: 72; max-width: 96%; height: auto; border: thick $accent;
    background: $surface; padding: 1 2;
}
RoleplayDraftNavigationDialog Vertical { height: auto; }
RoleplayDraftNavigationDialog Button { width: 100%; margin-top: 1; }

ArtifactShareDialog { align: center middle; background: $background 70%; }
ArtifactShareDialog > VerticalScroll {
    width: 76; max-width: 96%; height: auto; max-height: 90%;
    background: $surface; border: solid $primary; padding: 1 2;
}
ArtifactShareDialog Input, ArtifactShareDialog RadioSet, ArtifactShareDialog SelectionList {
    margin-bottom: 1;
}
ArtifactShareDialog #share-dialog-status { color: $warning; }

BackupRestoreScreen { background: $background; }
BackupRestoreScreen #backup-title { height: auto; padding: 1 2; text-style: bold; }
BackupRestoreScreen #backup-actions { layout: grid; grid-size: 2; grid-columns: 1fr 1fr; height: 6; padding: 0 1; }
BackupRestoreScreen #backup-actions Button { width: 100%; }
BackupRestoreScreen #backup-status { height: auto; max-height: 5; padding: 0 2; }
BackupRestoreScreen #backup-body { height: 1fr; padding: 1 2; }
BackupRestoreScreen .backup-form { height: auto; }
BackupRestoreScreen .backup-form Static { height: auto; margin-top: 1; }
BackupRestoreScreen .backup-form Input { width: 100%; }
BackupRestoreScreen .backup-form Checkbox { height: auto; width: 100%; }
BackupRestoreScreen #backup-message { height: auto; padding: 0 2; max-height: 4; }
BackupRestoreScreen #backup-footer-actions { height: auto; padding: 0 1; }
BackupRestoreScreen #backup-footer-actions Button { min-width: 10; width: 1fr; }

AutomationDefinitionForm {
    align: center middle;
}

AutomationDefinitionForm > VerticalScroll {
    width: 84;
    max-width: 100%;
    height: auto;
    max-height: 100%;
    background: $surface;
    border: thick $primary;
    padding: 1 2;
}

#automation-form-footer {
    dock: bottom;
    height: auto;
    background: $surface;
}

#automation-scope-sources-group,
#automation-run-at-group,
#automation-cron-group,
#automation-timezone-group,
#automation-preset-time-group,
#automation-cron-custom-group,
#automation-provider-group {
    height: auto;
}

#automation-form-errors {
    display: none;
}

#automation-question {
    height: 3;
    max-height: 5;
}

.form-title {
    text-style: bold;
    text-align: center;
    padding: 0;
}

.form-label {
    color: $text-muted;
    padding: 1 0 0 0;
}

.form-helper {
    color: $text-muted;
    height: auto;
    padding: 0;
}

.form-preview {
    color: $text-muted;
    height: auto;
    min-height: 1;
    padding: 0;
}

.error-text {
    color: $error;
    text-style: bold;
    height: auto;
    padding: 0;
}

.button-container {
    align: center middle;
    height: auto;
    padding: 0;
    margin-top: 1;
}

.button-container Button {
    margin: 0 1;
}

NewTaskChoiceModal {
    align: center middle;
}

NewTaskChoiceModal .new-task-choice-modal {
    width: 64;
    height: auto;
    border: tall $accent;
    background: $surface;
    padding: 1 2;
}

NewTaskChoiceModal .new-task-choice-title {
    text-style: bold;
    margin-bottom: 1;
}

NewTaskChoiceModal .new-task-choice-copy {
    height: auto;
    color: $text-muted;
    margin-bottom: 1;
}

NewTaskChoiceModal .new-task-choice-actions {
    height: 3;
    align-horizontal: right;
}

NewTaskChoiceModal .new-task-choice-actions Button {
    width: auto;
    margin-left: 1;
}

SkillRecoveryReviewModal { align: center middle; }
#skills-recovery-review { width: 90%; max-width: 110; height: 90%; border: tall $accent; padding: 1 2; background: $surface; }
#skills-recovery-scroll { height: 1fr; }
#skills-recovery-scroll Static { height: auto; margin-bottom: 1; }
#skills-recovery-actions { height: 3; align-horizontal: right; }
#skills-recovery-actions Button { width: auto; margin-left: 1; }
#skills-recovery-status { height: auto; color: $warning; }

ConsoleAppearancePickerModal {
    align: center middle;
}

#console-appearance-picker-modal {
    width: 64;
    max-width: 100%;
    height: 29;
    max-height: 100%;
    border: tall $accent;
    background: $panel;
    padding: 1 2;
}

#console-appearance-picker-filter {
    width: 100%;
    height: 3;
}

#console-appearance-picker-preview {
    width: 100%;
    height: 1;
    color: $text-muted;
}

#console-appearance-picker-emoji {
    width: 100%;
    height: 1fr;
    min-height: 6;
    background: $surface-darken-1;
}

#console-appearance-picker-colors {
    /* task-31209: a scrollable strip -- the 22-swatch palette (plus
       "none") no longer fits one modal row, and shrinking swatches to
       two cells left no content width under a selection border. */
    width: 100%;
    height: 3;
    margin-top: 1;
}

#console-appearance-picker-hex {
    width: 1fr;
    height: 3;
    margin-top: 1;
}

.console-appearance-swatch {
    width: 3;
    min-width: 3;
    max-width: 3;
    height: 3;
    min-height: 3;
    margin: 0;
    padding: 0;
    border: none;
    text-align: center;
    content-align: center middle;
}

.console-appearance-swatch-selected {
    /* Background highlight, not a border: the 2-cell swatch has no room
       for a 2-cell border (zero content width crashed cell chopping). */
    background: $accent 25%;
    text-style: bold;
}

#console-appearance-swatch-none {
    width: 5;
    min-width: 5;
    max-width: 5;
}

.console-appearance-emoji-selected {
    background: $accent 25%;
    text-style: bold;
}

#console-appearance-picker-actions {
    width: 100%;
    height: 3;
    margin-top: 1;
}

#console-appearance-picker-actions Button {
    width: 1fr;
    height: 3;
    border: none;
    margin: 0 1 0 0;
}

#console-appearance-picker-apply {
    background: $primary;
    color: $text;
}

#console-appearance-picker-clear,
#console-appearance-picker-cancel {
    background: $surface;
    color: $text;
}

ConsoleEditThinkingModal {
    align: center middle;
}

#console-edit-thinking-modal {
    width: 92;
    height: 28;
    border: tall gray;
    background: black;
    padding: 1 2;
}

#console-edit-thinking-context {
    height: auto;
    margin: 1 0 1 0;
}

#console-edit-thinking-body {
    width: 100%;
    height: 1fr;
    min-height: 8;
}

#console-edit-thinking-error {
    height: auto;
    min-height: 1;
    color: red;
}

#console-edit-thinking-actions {
    height: 3;
    min-height: 3;
    margin: 1 0 0 0;
    align-horizontal: right;
}

#console-edit-thinking-cancel,
#console-edit-thinking-save {
    width: 10;
    min-width: 10;
    height: 3;
    min-height: 3;
}

ConsoleEndpointTemplateModal {
    align: center middle;
}

ConsoleEndpointTemplateModal #console-endpoint-template-modal {
    width: 76;
    max-width: 95%;
    height: auto;
    max-height: 90%;
    border: round $panel;
    background: $surface;
    padding: 1 2;
}

ConsoleEndpointTemplateModal .console-settings-error {
    background: $error 25%;
    color: $text-error;
    text-style: bold;
    border-left: thick $error;
    height: auto;
    min-height: 1;
    margin: 1 0;
    padding: 0 1;
}

ConsoleEndpointTemplateModal #endpoint-template-picker {
    height: auto;
    max-height: 8;
    margin: 0 0 1 0;
}

ConsoleEndpointTemplateModal .console-endpoint-template-label {
    width: 16;
    min-width: 16;
    max-width: 16;
    height: 1;
    min-height: 1;
    content-align: left middle;
}

ConsoleEndpointTemplateModal .console-settings-modal-row {
    height: auto;
    min-height: 3;
}

ConsoleEndpointTemplateModal .console-settings-control {
    width: 1fr;
    min-width: 0;
}

ConsoleEndpointTemplateModal Input,
ConsoleEndpointTemplateModal Select,
ConsoleEndpointTemplateModal Button {
    height: 3;
    min-height: 3;
}

ConsoleEndpointTemplateModal #endpoint-template-params {
    height: 5;
    min-height: 3;
}

ConsoleEndpointTemplateModal .console-endpoint-template-hint {
    color: $text-muted;
    height: 1;
}

ConsoleEndpointTemplateModal .console-endpoint-template-actions {
    height: auto;
    min-height: 3;
    align-horizontal: right;
}

ConsoleProviderPicker {
    height: auto;
    width: 1fr;
}

ConsoleProviderPicker #console-settings-provider-picker-input {
    width: 100%;
}

ConsoleProviderPicker #console-settings-provider-picker-status {
    height: auto;
    color: $text-muted;
}

ConsoleProviderPicker #console-settings-provider-picker-results {
    max-height: 12;
}

ConsoleSaveMarkdownModal {
    align: center middle;
}
#console-save-markdown-box {
    width: 64;
    height: auto;
    border: round $primary;
    background: $surface;
    padding: 1 2;
}
#console-save-markdown-title {
    text-style: bold;
    margin-bottom: 1;
}
#console-save-markdown-input {
    width: 1fr;
}
#console-save-markdown-actions {
    height: auto;
    align-horizontal: right;
    margin-top: 1;
}

ConsoleTerminalSessionModal {
    align: center middle;
}

#console-terminal-session-modal {
    width: 72;
    max-width: 94%;
    height: auto;
    border: round $primary;
    background: $surface;
    padding: 1 2;
}

#console-terminal-session-error {
    min-height: 1;
    color: $error;
}

#console-terminal-session-actions {
    height: auto;
    margin-top: 1;
    align-horizontal: right;
}

WorkspaceArchiveReceiptModal { align: center middle; }
#workspace-archive-receipt { width: 60; height: auto; border: tall $primary;
    background: $surface; padding: 1 2; }
#workspace-archive-receipt-actions { height: 3; }
#workspace-archive-receipt-actions Button { width: auto; min-width: 8; margin-right: 1; }

NotesRecoveryDialog { align: center middle; }
#notes-recovery-dialog { width: 85%; max-width: 100; height: 85%;
    border: round $accent; background: $surface; padding: 1 2; }
#notes-recovery-rows { height: 1fr; }
#notes-recovery-actions { height: auto; }
#notes-recovery-dialog Static { height: auto; margin-bottom: 1; }

BuddyConversationModal { align: center middle; }
#buddy-conversation { width: 90; max-width: 96%; height: 90%; max-height: 52;
    border: round $accent; background: $panel; padding: 0 1; }
#buddy-conversation-title { height: 2; text-style: bold; }
#buddy-activity, #buddy-reply-notice { height: auto; }
#buddy-conversation-body { height: 1fr; min-height: 2; }
#buddy-transcript-navigation { height: 1; }
#buddy-transcript-navigation Button { height: 1; min-width: 8; width: auto; }
#buddy-transcript { height: auto; padding: 1 0; }
#buddy-reply { height: 5; min-height: 3; }
BuddyConversationModal.compact #buddy-reply { height: 3; }
BuddyConversationModal.compact #buddy-conversation-title { height: 1; }
#buddy-actions { height: 3; align-horizontal: right; }
#buddy-actions Button { min-width: 8; width: auto; margin-left: 1; }
#buddy-reply-notice { color: $text-muted; }

BuddyManagementModal { align: center middle; }
#buddy-management {
    width: 78; max-width: 96%; height: 90%; max-height: 48;
    border: round $accent; background: $panel; padding: 0 1;
}
#buddy-management-title { height: 2; text-style: bold; padding-top: 1; }
#buddy-management-body { height: 1fr; padding-right: 1; }
.buddy-section { height: auto; margin-top: 1; text-style: bold; }
.buddy-help { height: auto; color: $text-muted; }
#buddy-management-body Select, #buddy-management-body Input { width: 100%; }
.buddy-toggle-row { height: 3; align-vertical: middle; }
.buddy-toggle-row Static { width: 1fr; height: auto; }
.buddy-toggle-row Switch { width: auto; }
#buddy-size { height: 3; }
#buddy-management-body #buddy-size Input { width: 1fr; min-width: 4; }
#buddy-size Static { width: 9; height: 3; content-align: left middle; }
#buddy-size #buddy-height-label { width: 10; padding-left: 1; }
#buddy-preview { height: auto; max-height: 12; content-align: center middle; }
#buddy-artwork-pages { height: 3; }
#buddy-artwork-pages Button { width: auto; min-width: 10; }
#buddy-artwork-page { width: 1fr; content-align: center middle; }
#buddy-preview-actions { height: 3; }
#buddy-management-body #buddy-preview-state { width: 1fr; min-width: 10; }
#buddy-preview-button { width: auto; min-width: 11; }
#buddy-form-error, #buddy-import-error { height: auto; color: $error; }
#buddy-advanced { height: auto; padding: 0; }
#buddy-preview-button:focus { text-style: bold reverse; }
#buddy-management-actions { height: 3; min-height: 3; align-horizontal: right; }
#buddy-management-actions Button { width: auto; min-width: 10; margin-left: 1; }

BuddySpeechControls { height: auto; }
BuddySpeechControls Static { height: auto; }
BuddySpeechControls Horizontal { height: auto; }
BuddySpeechControls Button { min-width: 8; }

BuddyWorkspaceModal { align: center middle; }
#buddy-inbox {
    width: 82; max-width: 96%; height: 85%; max-height: 42;
    border: round $accent; background: $panel; padding: 0 1;
}
#buddy-inbox-title { height: 2; text-style: bold; padding-top: 1; }
#buddy-inbox-help { height: auto; color: $text-muted; }
#buddy-inbox-list { height: 1fr; margin-top: 1; }
#buddy-inbox-error { height: auto; color: $error; }
#buddy-inbox-actions { height: 3; min-height: 3; align-horizontal: right; }
#buddy-inbox-actions Button { width: auto; min-width: 8; margin-left: 1; }

ToolProfilesPanel {
    width: 100%;
    height: auto;
}

ToolProfilesPanel .tool-profiles-toolbar,
ToolProfilesPanel .tool-profile-actions {
    width: 100%;
    height: auto;
    layout: horizontal;
}

ToolProfilesPanel .tool-profile-row {
    width: 100%;
    height: auto;
    margin-bottom: 1;
    padding: 0 1;
    border: round $panel;
}

ToolProfilesPanel .tool-profile-title {
    width: 100%;
    text-style: bold;
}

ToolProfilesPanel .tool-profile-detail {
    width: 100%;
    color: $text-muted;
}

ToolProfilesPanel Button {
    width: auto;
    min-width: 8;
    height: 1;
    min-height: 1;
    padding: 0 1;
    border: none;
    margin-right: 1;
}

ToolProfilesPanel .tool-profile-actions Button {
    margin-right: 0;
}

WorkspaceChangeReviewPanel {
    height: auto;
}

WorkspacePersonaDefaultModal { align: center middle; }
#workspace-default-dialog { width: 68; max-width: 95%; height: auto; max-height: 95%;
    background: $surface; border: tall $primary; padding: 1 2; }
#workspace-default-form { height: auto; max-height: 17; }
#workspace-default-actions { height: 3; align-horizontal: right; }
#workspace-default-error { height: auto; color: $error; }

WorkspacePersonaPicker { height: auto; }
WorkspacePersonaPicker Static { height: auto; }
WorkspacePersonaPicker Select { height: 3; }
